// Package: Microsoft.EntityFrameworkCore.SqlServer
using Microsoft.EntityFrameworkCore;

public class BlogContext : DbContext
{
    private readonly string _connectionString;

    public BlogContext(DbContextOptions<BlogContext> options, string connectionString)
        : base(options)
    {
        _connectionString = connectionString;
    }

    public DbSet<Post> Posts => Set<Post>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        if (!optionsBuilder.IsConfigured)
        {
            optionsBuilder.UseSqlServer(_connectionString);
        }
    }
}

public class Post
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Content { get; set; } = string.Empty;
    public DateTime PublishedAt { get; set; }
}

// Program.cs registration
var builder = WebApplication.CreateBuilder(args);

// Connection string loaded from Secrets Manager (see secrets-manager-csharp lesson)
string connectionString = builder.Configuration.GetConnectionString("Default");

builder.Services.AddDbContext<BlogContext>(options =>
    options.UseSqlServer(connectionString));

builder.Services.AddScoped<BlogContext>(sp =>
    sp.GetRequiredService<BlogContext>());

var app = builder.Build();

app.MapGet("/posts", async (BlogContext db, CancellationToken ct) =>
{
    List<Post> posts = await db.Posts.ToListAsync(ct);
    return Ok(posts);
});

app.MapGet("/posts/{id}", async (int id, BlogContext db, CancellationToken ct) =>
{
    Post? post = await db.Posts.FindAsync([id], cancellationToken: ct);
    return post is not null ? Ok(post) : NotFound();
});

app.MapPost("/posts", async (Post post, BlogContext db, CancellationToken ct) =>
{
    db.Posts.Add(post);
    await db.SaveChangesAsync(ct);
    return CreatedAtAction(nameof(GetPost), new { id = post.Id }, post);
});

app.Run();

// Usage:
// GET /posts returns all posts from RDS SQL Server
// Expected output: [{"id":1,"title":"First Post","content":"Hello","publishedAt":"2024-01-15T00:00:00"}]

// Package: Microsoft.EntityFrameworkCore
using Microsoft.EntityFrameworkCore;

public static class DatabaseInitializer
{
    public static async Task InitializeAsync(IServiceProvider services, CancellationToken cancellationToken = default)
    {
        try
        {
            using var scope = services.CreateScope();
            var db = scope.ServiceProvider.GetRequiredService<BlogContext>();
            await db.Database.MigrateAsync(cancellationToken);
            Console.WriteLine("Database migrations applied successfully.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Migration error: {ex.Message}");
            throw;
        }
    }
}

// Usage in Program.cs:
// await DatabaseInitializer.InitializeAsync(app.Services);
// Expected output: "Database migrations applied successfully."
